#!/usr/bin/env node
/**
 * Applies committed SPM patches into node_modules after install.
 *
 * Why this exists: React Native's SPM autolinking requires some third-party
 * native modules (e.g. react-native-safe-area-context) to ship a `Package.swift`.
 * Those are generated by `npx react-native spm scaffold` into node_modules, but
 * node_modules isn't committed — and under pnpm with `node-linker=hoisted` a
 * fresh `pnpm install` re-extracts the package from the registry, wiping the
 * scaffolded file. `patch-package` only supports npm/yarn, and `pnpm patch`
 * fails to diff added files under the hoisted linker, so we persist the files
 * here and copy them back in deterministically on every install.
 *
 * To refresh a patch: re-run `npx react-native spm scaffold`, then copy the
 * regenerated file over the matching one under scripts/spm-patches/.
 */
const fs = require('fs');
const path = require('path');

const patchesRoot = path.join(__dirname, 'spm-patches');
if (!fs.existsSync(patchesRoot)) process.exit(0);

for (const pkg of fs.readdirSync(patchesRoot)) {
  const srcDir = path.join(patchesRoot, pkg);
  if (!fs.statSync(srcDir).isDirectory()) continue;

  const destDir = path.join(__dirname, '..', 'node_modules', pkg);
  if (!fs.existsSync(destDir)) {
    console.warn(`[spm-patches] skip ${pkg}: not installed`);
    continue;
  }

  for (const file of fs.readdirSync(srcDir)) {
    const src = path.join(srcDir, file);
    const dest = path.join(destDir, file);
    fs.copyFileSync(src, dest);
    console.log(`[spm-patches] applied ${pkg}/${file}`);
  }
}
